$(document).ready(function () {
  if (typeof Dashmix !== "undefined" && Dashmix.helpersOnLoad) {
    Dashmix.helpersOnLoad(["jq-validation"]);
  } else {
    console.error(
      "Dashmix is not loaded. Please include Dashmix before this script."
    );
    return;
  }

  // Custom validator for officer name: only letters and spaces, max 30 chars
  $.validator.addMethod(
    "officerName",
    function (value, element) {
      return this.optional(element) || /^[A-Za-z\s]{1,30}$/.test(value);
    },
    "Officer name must be letters only (max 30 characters, no numbers)."
  );

  $(".js-validation-nodel_officer").validate({
    rules: {
      state_id: {
        required: true,
      },
      district_id: {
        required: true,
      },
      nodel_officer_name: {
        required: true,
        officerName: true,
        maxlength: 30,
      },
      status: {
        required: true,
      },
    },
    messages: {
      state_id: {
        required: "Please select a state.",
      },
      district_id: {
        required: "Please select a district.",
      },
      nodel_officer_name: {
        required: "Please enter officer name.",
        officerName:
          "Officer name must be letters only (max 30 characters, no numbers).",
        maxlength: "Officer name cannot exceed 30 characters.",
      },
      status: {
        required: "Please select a status.",
      },
    },
    errorClass: "is-invalid",
    validClass: "is-valid",
    errorElement: "div",
    highlight: function (element) {
      $(element).addClass("is-invalid").removeClass("is-valid");
    },
    unhighlight: function (element) {
      $(element).addClass("is-valid").removeClass("is-invalid");
    },
    errorPlacement: function (error, element) {
      error.addClass("invalid-feedback");
      if (element.closest(".form-group").length) {
        element.closest(".form-group").append(error);
      } else if (element.closest(".mb-3").length) {
        element.closest(".mb-3").append(error);
      } else {
        element.after(error);
      }
    },
    submitHandler: function (form) {
      form.submit();
    },
    invalidHandler: function (event, validator) {
      if (validator.errorList.length) {
        $(validator.errorList[0].element).focus();
      }
    },
  });

  // Prevent manual submission if invalid
  $(".js-validation-nodel_officer").on("submit", function (e) {
    if (!$(this).valid()) {
      e.preventDefault();
    }
  });
});
